css:
.privacy-v2{--pbg:#0c0d0e;--pgold:#d9b363;--ppaper:#f5efe5;--pmuted:#c7c1b7;background:var(--pbg);color:var(--ppaper);font:16px/1.75 system-ui,-apple-system,"Segoe UI",sans-serif;overflow-wrap:break-word}
.privacy-v2 *, .privacy-v2 *:before,.privacy-v2 *:after{box-sizing:border-box}
.privacy-v2 a{color:#ebc87f;text-underline-offset:4px}
.privacy-v2 a:focus-visible,.privacy-v2 summary:focus-visible{outline:3px solid #eac77d;outline-offset:3px}
.privacy-v2 .privacy-hero-shell{background:radial-gradient(ellipse at 76% 4%,#4d3b1d30,transparent 45%),linear-gradient(#111214,#0c0d0e);border-bottom:1px solid #41372b}
.privacy-v2 .privacy-hero-inner,.privacy-v2 .privacy-layout{width:min(1210px,calc(100% - 44px));margin:0 auto}
.privacy-v2 .privacy-hero-inner{padding:28px 0 50px}
.privacy-v2 .customer-breadcrumb{margin:0;padding:0;font-size:12px;min-height:0;color:#bcb6ad}
.privacy-v2 .customer-breadcrumb ol{margin:0;padding:0;display:flex;flex-wrap:wrap;list-style:none;gap:10px}
.privacy-v2 .customer-breadcrumb li+li:before{content:'/';padding-right:10px;color:#8d8578}
.privacy-v2 .privacy-hero-intro{border:0;background:none;padding:0;margin:45px 0 0;max-width:780px}
.privacy-v2 .privacy-hero-intro .home-eyebrow{color:var(--pgold);font:750 11px/1.5 system-ui,sans-serif;letter-spacing:.16em;text-transform:uppercase;margin:0 0 14px}
.privacy-v2 .privacy-hero-intro h1{color:var(--ppaper);font:500 clamp(43px,5vw,72px)/1.1 Georgia,"Times New Roman",serif;letter-spacing:-.035em;margin:0 0 19px}
.privacy-v2 .privacy-hero-intro>p:last-child{color:var(--pmuted);font-size:17px;line-height:1.8;margin:0;max-width:675px}
.privacy-v2 .privacy-updated{display:inline-block;margin:20px 0 0;color:#ceb57e;font-size:12px}
.privacy-v2 .privacy-layout{display:grid;grid-template-columns:245px minmax(0,1fr);align-items:start;gap:38px;padding:46px 0 75px}
.privacy-v2 .privacy-sidebar{position:sticky;top:90px}
.privacy-v2 .privacy-toc{border:1px solid #41372b;border-radius:12px;background:#151617;padding:21px 14px}
.privacy-v2 .privacy-toc-title{font:750 11px/1.5 system-ui,sans-serif;letter-spacing:.15em;color:var(--pgold);text-transform:uppercase;margin:0 10px 15px}
.privacy-v2 .privacy-toc a,.privacy-v2 .privacy-mobile-toc a{display:flex;align-items:flex-start;gap:10px;padding:10px 11px;color:#d5cfc5;text-decoration:none;border-radius:6px;font-size:12px;line-height:1.5}
.privacy-v2 .privacy-toc a:hover,.privacy-v2 .privacy-mobile-toc a:hover{color:#f7dfa7;background:#27231c}
.privacy-v2 .privacy-toc a span,.privacy-v2 .privacy-mobile-toc a span{color:var(--pgold);font-size:11px;font-weight:700;flex-shrink:0}
.privacy-v2 .privacy-sidebar-note{padding:19px 12px;color:#c9c0b1;font-size:12px;line-height:1.65}
.privacy-v2 .privacy-sidebar-note a{display:block;font-weight:650;margin-top:7px}
.privacy-v2 .privacy-mobile-toc{display:none}
.privacy-v2 .privacy-content{min-width:0;counter-reset:pp-section}
.privacy-v2 .privacy-summary{background:linear-gradient(120deg,#202020,#131517);border:1px solid #8a703f;border-radius:14px;padding:31px;margin-bottom:25px}
.privacy-v2 .privacy-kicker{color:var(--pgold);text-transform:uppercase;font-size:11px;letter-spacing:.16em;font-weight:700;margin:0 0 12px}
.privacy-v2 .privacy-summary h2{font:500 clamp(26px,3vw,35px)/1.25 Georgia,serif;color:var(--ppaper);margin:0 0 22px}
.privacy-v2 .privacy-summary-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.privacy-v2 .privacy-summary-item{border:1px solid #514736;border-radius:9px;background:#141414;padding:16px 13px}
.privacy-v2 .privacy-summary-item strong{display:block;color:#e7c179;font-size:13px;margin:0 0 8px;font-weight:700}
.privacy-v2 .privacy-summary-item p{color:#d4cfc7;font-size:12px;line-height:1.65;margin:0}
.privacy-v2 .privacy-card{counter-increment:pp-section;margin:0 0 17px;padding:31px 34px;background:#141517;border:1px solid #3b362f;border-radius:12px;scroll-margin-top:94px}
.privacy-v2 .privacy-card h2{font:500 clamp(25px,3vw,34px)/1.25 Georgia,serif;color:var(--ppaper);letter-spacing:-.018em;display:flex;align-items:baseline;gap:15px;margin:0 0 18px}
.privacy-v2 .privacy-card h2:before{content:counter(pp-section,decimal-leading-zero);font:700 12px/1.6 system-ui,sans-serif;letter-spacing:.08em;color:var(--pgold)}
.privacy-v2 .privacy-card p{font:400 14px/1.9 system-ui,-apple-system,"Segoe UI",sans-serif;color:#d2cbc0;margin:0 0 13px;max-width:78ch}
.privacy-v2 .privacy-card p:last-child{margin-bottom:0}
.privacy-v2 .privacy-card h3{font:700 15px/1.5 system-ui,sans-serif;color:#ead7af;margin:21px 0 7px}
.privacy-v2 .privacy-card h3:first-of-type{margin-top:8px}
.privacy-v2 .privacy-cookie-help{margin-top:18px!important;border-top:1px solid #3e382b;padding-top:14px;font-size:13px!important}
.privacy-v2 .legacy-anchor{scroll-margin-top:90px}
.privacy-v2 .privacy-contact-card{display:flex;justify-content:space-between;gap:24px;align-items:center;padding:29px 32px;border-radius:12px;border:1px solid #9e7d40;background:linear-gradient(115deg,#252016,#191714)}
.privacy-v2 .privacy-contact-card h2{font:500 29px/1.25 Georgia,serif;color:var(--ppaper);margin:0 0 7px}
.privacy-v2 .privacy-contact-card p{font-size:13px;color:var(--pmuted);margin:0}
.privacy-v2 .privacy-contact-card a{flex-shrink:0;border:1px solid #d0aa5c;color:#18130e;background:#e1ba6d;border-radius:7px;padding:11px 18px;font-size:13px;font-weight:700;text-decoration:none;min-height:44px}
@media(max-width:940px){.privacy-v2 .privacy-layout{grid-template-columns:205px minmax(0,1fr);gap:22px}.privacy-v2 .privacy-summary-grid{grid-template-columns:1fr}.privacy-v2 .privacy-summary-item{padding:12px}.privacy-v2 .privacy-card{padding:26px}}
@media(max-width:740px){.privacy-v2 .privacy-hero-inner,.privacy-v2 .privacy-layout{width:calc(100% - 34px)}.privacy-v2 .privacy-hero-inner{padding:24px 0 35px}.privacy-v2 .privacy-hero-intro{margin-top:38px}.privacy-v2 .privacy-hero-intro>p:last-child{font-size:14px}.privacy-v2 .privacy-layout{display:block;padding:26px 0 60px}.privacy-v2 .privacy-sidebar{display:none}.privacy-v2 .privacy-mobile-toc{display:block;border:1px solid #685139;background:#181714;border-radius:12px;overflow:hidden;margin-bottom:21px}.privacy-v2 .privacy-mobile-toc summary{display:flex;align-items:center;justify-content:space-between;min-height:52px;padding:14px 17px;color:#f0d9a7;font-size:13px;font-weight:700;cursor:pointer;list-style:none}.privacy-v2 .privacy-mobile-toc summary::-webkit-details-marker{display:none}.privacy-v2 .privacy-mobile-toc summary:after{content:'⌄';font-size:19px}.privacy-v2 .privacy-mobile-toc[open] summary:after{content:'⌃'}.privacy-v2 .privacy-mobile-links{border-top:1px solid #574631;padding:5px}.privacy-v2 .privacy-summary{padding:23px 20px;margin-bottom:19px}.privacy-v2 .privacy-card{padding:22px 19px;margin-bottom:14px}.privacy-v2 .privacy-card h2{font-size:24px;gap:10px}.privacy-v2 .privacy-card p{font-size:14px;line-height:1.85}.privacy-v2 .privacy-contact-card{display:block;padding:22px 19px}.privacy-v2 .privacy-contact-card h2{font-size:25px}.privacy-v2 .privacy-contact-card a{display:inline-flex;margin-top:19px}}
@media(prefers-reduced-motion:reduce){.privacy-v2{scroll-behavior:auto}}
